// Private R2 fixture: checkpoint archive only, no latest pointer or DB authority.
import {createWebCrypto} from '../../../security/web-crypto.mjs';
import {r2ArtifactStore} from '../../../artifacts/r2';
import {createRefreshCheckpoints} from '../../../nfts/refresh-checkpoint.mjs';
import {createRefreshWorkflow} from '../../../nfts/refresh-workflow.mjs';
export default {async fetch(request:Request,env:Env){const body=await request.json() as any,cryptoPort=createWebCrypto();let gets=0,puts=0,faults=0;const bucket={get:async(...args:any[])=>{gets++;return (env.MANIFESTS.get as any)(...args);},put:async(...args:any[])=>{puts++;return (env.MANIFESTS.put as any)(...args);}},base=r2ArtifactStore(bucket as any),store={async putIfAbsent(identity:any,bytes:Uint8Array){if(body.fault==='unknown-missing'){faults++;return {status:'unknown' as const,identity};}const result=await base.putIfAbsent(identity,bytes);if(body.fault==='unknown-after-put'){faults++;return {status:'unknown' as const,identity};}return result;},async getVerified(identity:any){if(body.fault==='pin-mutation'&&!faults){faults++;body.pin.requestDigest='9'.repeat(64);body.pin.identity.byteDigest='8'.repeat(64);}const result=await base.getVerified(identity);if(body.fault==='lying-store'&&result.status==='verified'){faults++;const bytes=new Uint8Array(result.bytes);bytes[bytes.length-1]^=1;return {...result,bytes};}return result;}},service=createRefreshCheckpoints({crypto:cryptoPort,store});
 try{let result;if(body.method==='save')result=await service.save(body.state);else if(body.method==='restore')result=await service.restore(body.pin);else if(body.method==='replay'){const loaded=await service.restore(body.pin);if(loaded.kind!=='restored')result=loaded;else result=await createRefreshWorkflow({crypto:cryptoPort}).advance(loaded.state,body.event,body.metadata);}else throw Error('Unknown private checkpoint method');return Response.json({result,metrics:{gets,puts,faults,outputBytes:new TextEncoder().encode(JSON.stringify(result)).length}});}catch(error){return Response.json({error:(error as Error).message,metrics:{gets,puts,faults}});}
}};
